void get_face_boundary_vertices(Triangulation::Face_handle face, int edge, std::list<Triangulation::Vertex_handle>& vertices) {
    // Check if the edge is a boundary edge
    if (!face->is_shared_edge(edge)) {
        // Add the vertex of the boundary edge to the list
        vertices.push_back(face->vertex(edge));
        return;
    }

    // Get the neighbor face across the edge
    Triangulation::Face_handle neighbor = face->neighbor(edge);

    // Check if the neighbor face is interior and not yet processed
    if (neighbor->info().interior && !neighbor->info().processed) {
        // Mark as processed to avoid infinite recursion
        neighbor->info().processed = true;

        // Get the index of the edge in the neighbor
        int neighbor_index = neighbor->index(face);

        // Add the vertex on the other side of the edge
        vertices.push_back(neighbor->vertex((neighbor_index + 1) % 3));

        // Recursively get boundary vertices for the neighbor face
        get_face_boundary_vertices(neighbor, (neighbor_index + 2) % 3, vertices);
    }
}

